-//! Bounded model checking of vsr-rs with Kani.
+//! Conformance of the Rust replica to the Lean model in `lean/`.
 //!
-//! [`cluster`] drives a small cluster of real replicas and clients. The
-//! caller chooses every step: which message to deliver, which replica to
-//! tick, which client to make a request. After each step the cluster
-//! asserts the same properties the simulator checks. The harnesses in
-//! `harnesses` feed it symbolic choices, so `cargo kani` explores every
-//! delivery order, loss, replay, and view change within the harness bounds.
+//! A trace is a list of cluster steps: deliver a message, tick a replica,
+//! hand a replica a client request, or recover a replica. [`Cluster`]
+//! runs the real replicas through a trace and prints what it sees after
+//! each step. `lean/Main.lean` does the same with the model, in the same
+//! format, and the test in `verify_tests.rs` diffs the two.
 //!
-//! Run with `cargo kani -p vsr-verify`, or a single harness with
-//! `cargo kani -p vsr-verify --harness <name>`. Under a plain `cargo build`
-//! only the cluster driver and its unit tests compile.
+//! The network is the model's: every message ever sent stays in a list
+//! and any of them can be delivered at any time, so one rule covers loss,
+//! delay, replay, and reordering.

-// Kani's `assert!` takes its message as a plain literal, without
-// interpolation, so the variables named in the messages count as unused
-// under Kani only.
-#![cfg_attr(kani, allow(unused_variables))]
+use std::fmt::{self, Write};
+use vsr_rs::{ClientID, Config, LogEntry, Message, Replica, ReplicaID, Reply, StateMachine, Status};

-pub mod cluster;
+/// The state machine on both sides: it records every op and answers with
+/// how many it has applied.
+#[derive(Debug, Default)]
+pub struct Recorder {
+    pub applied: Vec<u64>,
+}

-#[cfg(kani)]
-mod harnesses;
+impl StateMachine for Recorder {
+    type Input = u64;
+    type Output = usize;
+
+    fn apply(&mut self, op: u64) -> usize {
+        self.applied.push(op);
+        self.applied.len()
+    }
+}
+
+/// One step of a trace.
+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+pub enum Step {
+    Deliver(usize),
+    Idle(ReplicaID),
+    Request {
+        to: ReplicaID,
+        client_id: ClientID,
+        request_number: usize,
+        op: u64,
+    },
+    Recover {
+        replica_id: ReplicaID,
+        nonce: u64,
+    },
+}
+
+impl fmt::Display for Step {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        match self {
+            Step::Deliver(i) => write!(f, "deliver {i}"),
+            Step::Idle(id) => write!(f, "idle {id}"),
+            Step::Request {
+                to,
+                client_id,
+                request_number,
+                op,
+            } => write!(f, "request to={to} client={client_id} request={request_number} op={op}"),
+            Step::Recover { replica_id, nonce } => write!(f, "recover {replica_id} nonce={nonce}"),
+        }
+    }
+}
+
+#[derive(Clone, Debug)]
+pub struct Trace {
+    pub replica_count: usize,
+    pub primary_timeout: usize,
+    pub steps: Vec<Step>,
+}
+
+impl fmt::Display for Trace {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        writeln!(
+            f,
+            "config replicas={} timeout={}",
+            self.replica_count, self.primary_timeout
+        )?;
+        for step in &self.steps {
